query RaygunUserTracking {
  viewer {
    id
    ... on ExternalStaff {
      firstName
      lastName
      emailAddress
      __typename
    }
    ... on NationalOfficeStaff {
      firstName
      lastName
      emailAddress
      __typename
    }
    ... on Member {
      firstName
      lastName
      emailAddress
      __typename
    }
    __typename
  }
}
